import {React, useState, useEffect} from 'react';
import { Table } from 'rsuite';

const TableRides = (props) => {
    const [error, setError] = useState(null);
    const [isLoaded, setIsLoaded] = useState(false);
    const [data, setData] = useState([]);
    const [columnsVisible, setColumnsVisible] = useState(props.columnsVisible);
    const [titleTable, setTitleTable] = useState(props.title);
    const { Column, HeaderCell, Cell } = Table;

    

  if (error) {
    return <div>Erreur : {error.message}</div>;
  } else if (!isLoaded) {
    return <div>Chargement...</div>;
  } else {
    return (
        <Table virtualized height={400} data={data}>
            <Column width={130}>
                <HeaderCell>firstname</HeaderCell>
                <Cell dataKey="firstname" />
            </Column>
            <Column width={130}>
                <HeaderCell>Last Name</HeaderCell>
                <Cell dataKey="lastName" />
            </Column>
            <Column width={100}>
                <HeaderCell>Gender</HeaderCell>
                <Cell dataKey="gender" />
            </Column>
            <Column width={100}>
                <HeaderCell>Age</HeaderCell>
                <Cell dataKey="age" />
            </Column>
            <Column width={200}>
                <HeaderCell>City</HeaderCell>
                <Cell dataKey="city" />
            </Column>
            <Column width={200}>
                <HeaderCell>Email</HeaderCell>
                <Cell dataKey="email" />
            </Column>
        </Table>
    );
  }

    
}
export { TableRides };
